class Solution {
public:
    int countKDifference(vector<int>& nums, int k) {
        int c=0;
        for(int i=0; i<nums.size(); i++){
            for(int j=i+1; j<nums.size(); j++){
                if(abs(nums[i]-nums[j])==k){
                    c+=1;
                }
            }
        }
        return c;
    }
};

const unsigned long long C = 1ull << 63;
struct Bitbuf {
    unsigned long long data[2];

    void set(int x) {
        if( x<64 ) {
            data[0] |= 1 << x;
        } else {
            data[1] |= 1 << (x-64);
        }
    }

    void setzero() {
        data[0] |= 1;
    }

    void merge(Bitbuf const& other) {
        data[0] |= other.data[0];
        data[1] |= other.data[1];
    }

    void copy(Bitbuf const& other) {
        data[0] = other.data[0];
        data[1] = other.data[1];
    }

    void copy_and_shift(Bitbuf const& other, int dir) {
        copy(other);
        shift(dir);
    }

    void init() {
        data[0] = 1ull;
        data[1] = 0ull;
    }


    void inc() {
        data[1] <<= 1ull;
        if( (data[0]&C)==C ) {
            data[1] |= 1ull;
        }
        data[0] <<= 1ull;
    }

    void dec() {
        data[0] >>= 1ull;
        if( (data[1]&1ull)==1ull ) {
            data[0] |= C;
        }
        data[1] >>= 1ull;
    }

    void shift(int d) {
        if( d>0 ) {
            inc();
        } else {
            dec();
        }
    }

    bool contains_zero() {
        return (data[0]&1ull)==1ull;
    }

};

class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        const int R=grid.size(), C=grid[0].size();
        vector<vector<Bitbuf>> buf(2, vector<Bitbuf>(C));
        auto val = [&](int r, int c) {
            switch (grid[r][c]) {
                case '(': return 1;
                default: return -1;
            }
        };
        if( grid[0][0]==')' || grid.back().back()=='(' ) {
            return false;
        }
        buf[0][0].init();
        buf[0][0].shift(val(0, 0));

        for( int c=1;c<C;++c ) {
            buf[0][c].copy_and_shift(buf[0][c-1], val(0, c));

        }
        for( int r=1;r<R;++r ) {
            int curr = r%2;
            int pref = (r+1)%2;
            buf[curr][0].copy_and_shift(buf[pref][0], val(r, 0));
            for( int c=1;c<C;++c ) {
                buf[curr][c].copy(buf[curr][c-1]);
                buf[curr][c].merge(buf[pref][c]);
                buf[curr][c].shift(val(r, c));
            }
        }

        return buf[(grid.size()+1)%2].back().contains_zero();
    }
};

class Solution {
public:
    bool isValid(string str) {
        if (str.size() % 2)
            return 0;

        int j = 0;

        for (char s : str)
            if ((s & 3) != 1)
                str[j++] = s;
            else if (j == 0 || ((s - str[--j] + 1) >> 1) != 1)
                return 0;

        return j == 0;
    }
};

class Solution {
    vector<int> res;
    vector<int> done;

    void f(const vector<int>& A, int i) {
        if (i == 15) return;
        if (done[i]) {
            f(A, i + 1);
            return;
        }
        vector<int> L, R;
        for (int a : A) {
            if (a & (1 << (14 - i))) {
                L.push_back(a);
            } else {
                R.push_back(a);
            }
        }
        if (!L.empty()) {
            res[i] += L.size();
            f(L, i + 1);
        }
        if (!R.empty()) {
            done[i] = 1;
            f(R, i + 1);
        }
    }

public:
    vector<int> largestPower(vector<int>& A) {
        res.assign(15, 0);
        done.assign(15, 0);
        f(A, 0);
        return res;
    }
};
